    Estimates build time based on code complexity, module count, team size,
    and task optimization insights from other modules.
    """

    def __init__(self):
        self.base_time_per_complexity = {
            "O(1)": 0.1,
            "O(log n)": 0.2,
            "O(n)": 0.5,
            "O(n log n)": 1.0,
            "O(n^2)": 3.0,
            "O(2^n)": 10.0
        }

    def estimate(self, task_tracker: DevelopmentTaskTracker, team_size: int = 1) -> dict:
        """
        Estimate total build time using task data and efficiency insights.
        Returns estimated time (in minutes) and breakdown.
        """
        tasks = task_tracker.get_all_tasks()
        if not tasks:
            return {"total_minutes": 0, "breakdown": [], "confidence": 0.0}

        total_time = 0.0
        breakdown = []

        for task in tasks:
            # Base time from code complexity (if available)
            complexity = "O(n)"  # default
            if task.get("efficiency_analysis"):
                complexity = task["efficiency_analysis"].get("time_complexity", "O(n)")

            base_time = self.base_time_per_complexity.get(complexity, 0.5)

            # Adjust for inefficiencies
            inefficiency_penalty = len(task.get("efficiency_analysis", {}).get("inefficiencies", [])) * 0.3

            # Adjust for task priority (higher priority = more attention = faster)
            priority_factor = 1.0 - (task.get("priority", 1) - 1) * 0.1

            # Team size scaling (more devs = parallelization, but diminishing returns)
            parallel_factor = max(0.2, 1.0 / (team_size ** 0.5))

            task_time = base_time * (1 + inefficiency_penalty) * priority_factor * parallel_factor
            total_time += task_time

            breakdown.append({
                "task_id": task["id"],
                "title": task["title"],
                "estimated_minutes": round(task_time, 2),
                "complexity": complexity
            })

        return {
            "total_minutes": round(total_time, 2),
            "breakdown": breakdown,
            "confidence": 0.85 - (len(tasks) * 0.01),  # Slight confidence drop with more tasks
            "team_size_used": team_size
        }


